#!/usr/bin/env python3
"""Build sealed preparation metadata; no CFD invocation."""
import csv,hashlib,json,math,re,shutil,subprocess
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[3]
ctx=json.loads((P/'preparation_context.json').read_text());C=Path(ctx['case']);S=Path(ctx['source']);HEAD=json.loads((P/'head_review.json').read_text())['reviewed_current_HEAD']
def sha(f):return hashlib.sha256(Path(f).read_bytes()).hexdigest()
def save(name,x):(P/name).write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
old=json.loads((S/'production_input_manifest.json').read_text());report=json.loads((S/'head_review_v2/RouteA_plain_transient_Co05_production_report_v2.json').read_text());result=json.loads((S/'execution_v2/execution_result.json').read_text())
# Co05 saved-output authorities and historical source inputs are immutable.
refs=json.loads((S/'source_reference_guard.json').read_text())
for directory in [S/'postprocessing_v2',S/'head_review_v2']:
 manifest=directory/('postprocessing_artifact_manifest_sha256.json' if directory.name=='postprocessing_v2' else 'final_v2_artifact_manifest_sha256.json')
 for rel,h in json.loads(manifest.read_text()).items():refs[str((directory/rel).relative_to(ROOT))]=h
for name in ['production_input_manifest.json','production_execution_plan.json','production_postprocessing_plan.md','execution_v2/execution_result.json','execution_v2/log.foamRun']:
 f=S/name;refs[str(f.relative_to(ROOT))]=sha(f)
save('source_reference_guard.json',refs)
m=old.copy();m.update(preparation_id=P.name,case=str(C),case_files_sha256={str(f.relative_to(C)):sha(f) for f in sorted(C.rglob('*')) if f.is_file()},source_reference_guard_sha256=sha(P/'source_reference_guard.json'),production_execution_authorized='NO')
save('production_input_manifest.json',m)
dt05=report['runtime']['late_deltaT_seconds']['median'];late25=dt05/2;actualsteps=report['runtime']['completed_physical_steps'];bytesper=report['runtime']['log_bytes']/actualsteps
rows=list(csv.DictReader((S/'postprocessing_v2/native_step_diagnostics.csv').open()));previous=2.3111979166666666e-5;frozen_state_step_proxy=0.
for row in rows:
 co=float(row['Co_max']);stepdt=float(row['deltaT_s']);allowed=min(.027734375,.25*previous/co) if co>1e-15 else .027734375
 frozen_state_step_proxy+=max(1.,stepdt/allowed);previous=stepdt
fields=report['actual_storage']['native_output_allocated_bytes'];fieldprojection=math.ceil(fields/294*296);markers=(S/'execution_v2/time_header_wall_markers.json').stat().st_size/actualsteps
postactual=sum(f.stat().st_blocks*512 for f in (S/'postprocessing_v2').rglob('*') if f.is_file());scenarios=[]
for n in [280000,300000,320000]:
 log=math.ceil(n*bytesper);mark=math.ceil(n*markers);total=fieldprojection+log+mark+math.ceil(postactual*2)
 scenarios.append({'steps':n,'projected_log_bytes':log,'projected_native_fields_allocated_bytes':fieldprojection,'projected_marker_bytes':mark,'postprocessing_budget_bytes':math.ceil(postactual*2),'projected_total_bytes':total,'hours_at_Co05_mean_seconds_per_step':n*(report['runtime']['total_wall_seconds']/actualsteps)/3600,'hours_at_Co05_late_seconds_per_step':n*report['runtime']['late_external_seconds_per_step_excluding_native_writes']['median']/3600})
projection={'classification':'PLANNING_ESTIMATE_NOT_STOP_CONDITION','Co05_measured_log_bytes_per_step':bytesper,'Co05_actual_storage':report['actual_storage'],'Co025_expected_late_dt_s':late25,'Co05_fixed_state_inverse_flux_step_proxy':frozen_state_step_proxy,'proxy_limitation':'Uses Co05 flux/rho states and local allowable dt; not a Co025 trajectory/controller simulation. Growth and changed transient fields make actual counts uncertain.','planning_steps':[280000,300000],'central_steps':2*actualsteps,'planning_runtime_hours':[4,6],'central_hours_at_Co05_average_cost':2*report['runtime']['total_wall_hours'],'solver_cost_uncertainty':'Co05 pressure iterations fell from early1000 median2383 to late median35, energy late median0; Co025 cost is unmeasured.','snapshot_upper_bound':296,'scenarios':scenarios,'production_prelaunch_free_bytes':32*1024**3,'runtime_low_watermark_bytes':8*1024**3,'conservative_projection_with_25percent_margin_plus_low_watermark_bytes':math.ceil(max(x['projected_total_bytes'] for x in scenarios)*1.25)+8*1024**3,'current_free_bytes':shutil.disk_usage(C).free}
assert projection['conservative_projection_with_25percent_margin_plus_low_watermark_bytes']<32*1024**3
projection['disk_capacity_pass']=projection['current_free_bytes']>=32*1024**3;save('storage_projection.json',projection)
scripts=['production_launcher.py','run_production.sh','head_integrity.py','postprocess_production.py','postprocess_and_compare.py','mesh_geometry.py','mesh_geometry.npz']
sensitive={str(C/rel):h for rel,h in m['case_files_sha256'].items()}
for rel,h in refs.items():sensitive[str(ROOT/rel)]=h
for v in m['binary_provenance'].values():sensitive[v['path']]=v['sha256']
sensitive.update(m['installed_source_sha256'])
for f,h in report['native_Co_controller_alignment']['source_sha256'].items():assert sha(f)==h;sensitive[f]=h
for name in scripts:sensitive[str(P/name)]=sha(P/name)
save('production_sensitive_manifest.json',{'preparation_id':P.name,'reviewed_HEAD':HEAD,'files_sha256':sensitive,'plan_and_authorization_hash_pins':'execution_package_seal.json','intended_difference_from_Co05':'maxCo0.5→0.25 only; auxiliary startup sampling physical-time based'})
launcher={name:sha(P/name) for name in scripts};save('launcher_artifact_manifest.json',launcher)
plan=json.loads((S/'production_execution_plan.json').read_text());argv=plan['command_argv'].copy();argv[argv.index('-case')+1]=str(C)
plan.update(preparation_id=P.name,case=str(C),prep_results=str(P),runtime_output=str(P/'execution'),expected_HEAD=HEAD,reviewed_current_HEAD=HEAD,input_manifest_file=str(P/'production_input_manifest.json'),input_manifest_sha256=sha(P/'production_input_manifest.json'),production_sensitive_manifest_sha256=sha(P/'production_sensitive_manifest.json'),command_argv=argv,command_shell=' '.join(argv),cwd=str(C),maxCo=.25,startup_write_steps=[],startup_write_physical_times_s=[s['value'] for s in result['saved_snapshot_times_and_indices'][:10]],startup_additional_events=['first_maxDeltaT_if_reached','first_Co_control'],expected_full_field_snapshots_upper_bound=296,expected_steps_planning_range=[280000,300000],expected_runtime_hours=2*report['runtime']['total_wall_hours'],expected_runtime_hours_range=[4,6],runtime_classification='PROJECTED_FROM_COMPLETED_CO05_NOT_A_CO025_MEASUREMENT',updated_HEAD_policy='Reviewed descendant results/non-authority-doc drift allowed after sensitive hash verification; sensitive/unknown changes fail closed.',launcher_artifact_manifest_sha256=sha(P/'launcher_artifact_manifest.json'),startup_IO_signal_policy='SIGUSR1 to verified rank0 after observed Time header crosses physical targets or first cap/controller event; approximate asynchronous observation, actual uniform/time values audited offline. Writes never change dt or stop.',PRODUCTION_EXECUTION_AUTHORIZED='NO')
save('production_execution_plan.json',plan)
draft={'AUTHORIZED':'NO','TASK':'PREPARE_ROUTE_A_PLAIN_TRANSIENT_CO025_PRODUCTION_RUN','authorization_class':'ROUTE_A_PLAIN_TRANSIENT_CO025_PRODUCTION','preparation_id':P.name,'reviewed_execution_HEAD':HEAD,'execution_plan_sha256':sha(P/'production_execution_plan.json'),'input_manifest_sha256':plan['input_manifest_sha256'],'production_sensitive_manifest_sha256':plan['production_sensitive_manifest_sha256'],'MPI_RANKS':12,'maxCo':.25,'endTime_s':1420,'CO025_ALLOWED':'NO','CO05_ALLOWED':'NO','AUTOMATIC_RESTART':'NO','AUTOMATIC_RERUN':'NO','Q3_ALLOWED':'NO','FORMAL_GATE_J_ALLOWED':'NO','later_execution_requires':'A separate YES receipt from explicit RUN_ROUTE_A_PLAIN_TRANSIENT_CO025_PRODUCTION user instruction; do not edit this sealed NO draft.'};save('production_authorization_draft.json',draft)
postplan=json.loads((S/'production_postprocessing_plan.json').read_text());postplan.update(preparation_id=P.name,script=str(P/'postprocess_and_compare.py'),command_argv=['/usr/bin/python3','-B',str(P/'postprocess_and_compare.py'),'--execute'],execution='AFTER_NORMAL_COMPLETED_NATIVE_ENDTIME_ONLY',primary_comparison='fixed-grid Co0.5 vs Co0.25; same160² steady baseline secondary',comparison_authority=str(P/'source_Co05_comparison_authority.json'),comparison_axis='physical time or tstar; never step index',history_interpolation={'method':'piecewise linear','grid':'union of both saved tstar axes within common overlap, including common endpoints','extrapolation':False,'time_range':'[max(min tstar05,min tstar025), min(max tstar05,max tstar025)]','RMS':'sample RMS plus trapezoidal time-weighted RMS','limitations':'stored-state interpolation includes sampling error; no unsaved extrema claims'},sensitivity_metrics=['signed/absolute/relative final QoI difference','maximum sampled history difference','RMS sampled history difference','last10% common-window difference','final U/W/theta profile RMS/Linf differences'],two_level_temporal_convergence_proven=False,Co0125_policy='Decide only after Co025 data: materially different QoIs/profiles/trajectories or unresolved sensitivity may justify a reviewed Co0125 study; resolve output/horizon error first; no run currently authorized.')
save('production_postprocessing_plan.json',postplan)
text=(S/'production_postprocessing_plan.md').read_text();text='# Co0.25 offline comparison preparation\n\nPrimary purpose: fixed-grid timestep sensitivity between Co0.5 and Co0.25. Future command: `'+ ' '.join(postplan['command_argv'])+'`. Requires a completed normal native result. No CFD is invoked by postprocessing.\n\nHistories are compared by t*, using piecewise linear interpolation onto the union of saved t* values in the common overlap; extrapolation is forbidden. Record axis/range, sample and time-weighted RMS, maximum differences and last10% common-window metrics. Direct final-native QoIs and profiles retain actual final-time differences; no forced exact1420 assumption. Sparse saved-time interpolation cannot recover unsaved extrema. A descriptive0.1% criterion may label small final/late sensitivity; inspect full history/profile metrics before a broader statement. Two levels cannot prove temporal convergence or independence. Co0.125 is a post-data review option, not predetermined.\n\n'+'Shared Co05 scientific methodology retained below as historical reference; its old command is not the Co025 execution command.\n\n'+text
(P/'production_postprocessing_plan.md').write_text(text)
names=['production_execution_plan.json','production_input_manifest.json','production_sensitive_manifest.json','launcher_artifact_manifest.json','production_authorization_draft.json','source_reference_guard.json',*scripts,'source_Co05_comparison_authority.json','production_postprocessing_plan.json','production_postprocessing_plan.md']
save('execution_package_seal.json',{name:sha(P/name) for name in names})
print(json.dumps({'steps_proxy':frozen_state_step_proxy,'late_dt25':late25,'central_steps':2*actualsteps,'runtime_hours_range':[4,6],'sensitive_files':len(sensitive),'scenarios':scenarios},indent=2))
